def solve(nums, k):
    def count_less_equal(x):
        return sum(1 for num in nums if num <= x)

    left, right = min(nums), max(nums)

    while left < right:
        mid = (left + right) // 2
        cnt = count_less_equal(mid)
        if cnt < k:
            left = mid + 1
        else:
            right = mid
    return left
